import java.util.ArrayDeque;

public class Main {
    public static void main(String[] args) {
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(1); //~ push puts a plate on TOP of the stack.
        stack.push(2);
        stack.push(3);
        System.out.println(stack.pop()); //~ pop takes the top plate: the LAST one pushed.
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        queue.offer(1); //~ A queue: join at the back…
        queue.offer(2);
        queue.offer(3);
        System.out.println(queue.poll()); //~ …and leave from the front. First in, first out.
    }
}

